            // if requesting value from a local file, don't return values from local files in different worktrees
            continue;
        }

        let Some(content) = self.get_content_for_file(file.clone()) else {
            continue;
        };
        if get(content).is_some() {
            overrides.push(file);
        }
    }

    overrides
